import java.util.ArrayList;
import java.util.List;

public class RosterSnapshotTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            List<String> src = new ArrayList<>();
            src.add("ann");
            src.add("bob");
            int[] raw = { 4, 6 };

            RosterSnapshot snap = new RosterSnapshot(src, raw);
            check("size", 2, snap.size());
            check("total", 10, snap.total());
            check("nameAt(1)", "bob", snap.nameAt(1));
            check("nameAt(9) out of range", "", snap.nameAt(9));
            check("nameAt(-1) out of range", "", snap.nameAt(-1));

            src.add("cid");
            raw[0] = 999;
            check("size after caller mutates the source list", 2, snap.size());
            check("total after caller mutates the source array", 10, snap.total());

            List<String> handedOut = snap.getNames();
            handedOut.clear();
            check("size after caller clears the returned list", 2, snap.size());
            check("getNames content", "[ann, bob]", snap.getNames().toString());

            int[] copy = snap.getScores();
            check("getScores content", "[4, 6]", java.util.Arrays.toString(copy));
            copy[1] = -50;
            check("total after caller edits the returned array", 10, snap.total());

            RosterSnapshot empty = new RosterSnapshot(null, null);
            check("null arguments give size 0", 0, empty.size());
            check("null arguments give total 0", 0, empty.total());
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

